<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {PRICE_FIELDS,createPricePolicyApi,validPriceBody,priceLocalUtc,priceBeijing} from '../../services/price-policies.js'
import {createPricePolicyRecovery} from '../../services/price-policy-recovery.js'
import {imageRequestKey} from '../../services/private-images.js'
const fresh=()=>({lower:'',upper:'',unit:'',applicability:'',note:'',confirmed:false,from:'',to:'',revision:0})
const state=reactive(initialDiagnosisState()),form=reactive(fresh()),selected=ref(null),editing=ref(0),sourcePage=ref(1),confirmation=ref(null),api=createPricePolicyApi(),allowed=()=>operatorSession.canPriceMonitor,blocked=()=>state.busy||state.retry||state.kind==='storage'
const recovery=createPricePolicyRecovery({actor:()=>operatorSession.actorId})
function clearForm(){selected.value=null;editing.value=0;confirmation.value=null;Object.assign(form,fresh())}
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`price-policy:${operatorSession.actorId}`,recovery,newKey:imageRequestKey,load:async(t,p)=>{const [policies,quotes]=await Promise.all([api.list(t,p),api.quotes(t,sourcePage.value)]);return {...policies,quotes}},write:api.write,onWritten:clearForm,confirm:action=>new Promise(resolve=>{const q=confirmation.value;uni.showModal({title:action==='discard-local'?'核对并清理本机请求':'确认报价版本依据',content:action==='discard-local'?'请核对刚读取的服务器记录。此操作仅清理本机未决请求。':q?`${q.source.merchant.name} · ${q.source.project.project_name}\n报价版本 ${q.source.quote_version}，当前 ¥${q.source.price}\n内容：${q.source.project.service_content}\n区间含边界：¥${q.lower_price} 至 ¥${q.upper_price}／${q.price_unit}\n适用：${q.applicability_note}\n来源：${q.source_note}\n北京时间 ${priceBeijing(q.valid_from)} 至 ${priceBeijing(q.valid_to)}（不含）\n发布后冻结，只能停止；配置本身不生成偏离判断，请另行读取比较。`:'请重新读取后确认。',success:r=>resolve(r.confirm&&Boolean(q||action==='discard-local')),fail:()=>resolve(false)})})})
let visible=false
function choose(q){if(blocked()||q.state!=='READY')return;selected.value=JSON.parse(JSON.stringify(q));form.confirmed=false}
function edit(p){if(blocked())return;editing.value=p.id;selected.value={quote_id:p.quote_id,state:'READY',source:JSON.parse(JSON.stringify(p.source_snapshot)),source_hash:p.source_hash};Object.assign(form,{lower:p.lower_price,upper:p.upper_price,unit:p.price_unit,applicability:p.applicability_note,note:p.source_note,confirmed:false,from:priceBeijing(p.valid_from),to:priceBeijing(p.valid_to),revision:p.revision})}
function save(){if(blocked())return;const action=editing.value?'update':'create',b={quote_id:selected.value?.quote_id,source_hash:selected.value?.source_hash,lower_price:form.lower,upper_price:form.upper,price_unit:form.unit.trim(),applicability_note:form.applicability.trim(),source_note:form.note.trim(),scope_confirmed:form.confirmed,valid_from:priceLocalUtc(form.from),valid_to:priceLocalUtc(form.to),...(editing.value?{expected_revision:form.revision}:{})};if(!validPriceBody(b,action)){state.message='请选择已核验报价，确认内容及范围，并填写正数两位区间、单位、适用说明、来源和未来生效时间。';return}confirmation.value=JSON.parse(JSON.stringify({...b,source:selected.value.source}));flow.save(action,editing.value,b)}
function setStatus(p,status){if(blocked())return;confirmation.value={...Object.fromEntries(PRICE_FIELDS.map(k=>[k,p[k]])),source:p.source_snapshot};flow.save('status',p.id,{expected_revision:p.revision,status})}
function sourceNext(n){if(blocked())return;sourcePage.value+=n;flow.load(state.page)}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function reset(){flow.reset();clearForm();sourcePage.value=1}
watch(()=>[operatorSession.accessToken,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k))clearForm()})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
</script>
<template><view class="reservation-page"><text class="reservation-title">价格监控来源依据</text><text>按具体报价版本确认内容、计价单位和车型适用性。没有有效来源为未知。配置依据后可单独读取当前报价比较；旧回执不代表当前比较结果。</text><button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有独立价格监控权限。</text><template v-else><text v-if="state.busy" role="status">正在核验报价和来源依据…</text><text v-if="state.message" role="status">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原依据请求</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器并清理本机请求</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新依据与报价</button><view v-if="state.data" class="reservation-panel"><text class="reservation-heading">当前报价来源</text><text v-if="!state.data.quotes.items.length">没有当前可读取的上架报价。</text><view v-for="q in state.data.quotes.items" :key="q.quote_id"><text>{{q.source.merchant.name}} · {{q.source.project.project_name}} · ¥{{q.source.price}} · 版本 {{q.source.quote_version||'未知'}}</text><text>{{q.source.project.service_content}}</text><text>原项目来源：{{q.source.project.source_note||'未知'}}</text><text v-if="q.state!=='READY'">版本或保存凭证不完整，当前来源未知。</text><button :disabled="blocked()||q.state!=='READY'" @tap="choose(q)">选择此报价来源</button></view><button v-if="sourcePage>1" :disabled="blocked()" @tap="sourceNext(-1)">上一页报价</button><button v-if="sourcePage*20<state.data.quotes.total" :disabled="blocked()" @tap="sourceNext(1)">下一页报价</button></view><view class="reservation-panel"><text class="reservation-heading">{{editing?'修改依据草稿':'新建依据草稿'}}</text><template v-if="selected"><text>{{selected.source.merchant.name}} · {{selected.source.project.project_name}} · 版本 {{selected.source.quote_version}}</text><text>{{selected.source.project.service_content}}</text><text>质量标准：{{selected.source.project.quality_standard||'未提供'}}</text><text>地区：{{selected.source.merchant.region_code||'未提供'}}</text></template><input v-model="form.lower" type="digit" maxlength="11" :disabled="blocked()" placeholder="含边界价格下限，例如两位小数"/><input v-model="form.upper" type="digit" maxlength="11" :disabled="blocked()" placeholder="含边界价格上限"/><input v-model="form.unit" maxlength="32" :disabled="blocked()" placeholder="计价单位"/><textarea v-model="form.applicability" maxlength="256" :disabled="blocked()" placeholder="车型、服务内容及适用范围说明"/><textarea v-model="form.note" maxlength="256" :disabled="blocked()" placeholder="该版本区间与适用性的来源说明"/><text>北京时间，截止不含；保存及发布时须仍为未来时间</text><input v-model="form.from" maxlength="19" :disabled="blocked()" placeholder="生效 YYYY-MM-DD HH:mm:ss"/><input v-model="form.to" maxlength="19" :disabled="blocked()" placeholder="截止 YYYY-MM-DD HH:mm:ss"/><checkbox-group @change="form.confirmed=$event.detail.value.includes('confirmed')"><label><checkbox value="confirmed" :checked="form.confirmed" :disabled="blocked()"/>确认所选报价版本服务内容、计价单位及车型适用说明与本依据一致</label></checkbox-group><button :disabled="blocked()||!selected" @tap="save">保存依据草稿</button><button :disabled="blocked()" @tap="clearForm">新建另一依据</button></view><template v-if="state.data"><text v-if="!state.data.items.length">尚无来源依据，不使用项目参考价自动判断。</text><view v-for="p in state.data.items" :key="p.id" class="reservation-panel"><text class="reservation-heading">{{p.source_snapshot.merchant.name}} · {{p.source_snapshot.project.project_name}} · {{p.status}} · 修订 {{p.revision}}</text><text>绑定报价版本 {{p.source_snapshot.quote_version}} · ¥{{p.lower_price}} 至 ¥{{p.upper_price}}／{{p.price_unit}}（含边界）</text><text>{{p.applicability_note}}</text><text>{{p.source_note}}</text><text>北京时间 {{priceBeijing(p.valid_from)}} 至 {{priceBeijing(p.valid_to)}}（截止不含）</text><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="edit(p)">修改草稿并重新确认</button><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="setStatus(p,'PUBLISHED')">发布并冻结</button><button v-if="p.status==='PUBLISHED'" :disabled="blocked()" @tap="setStatus(p,'STOPPED')">停止依据</button></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页依据</button><button v-if="state.page*20<state.data.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页依据</button></template></template><button v-if="allowed()" @tap="uni.navigateTo({url:'/pages/operator/price-comparisons'})">只读价格比较</button><button @tap="uni.navigateTo({url:'/pages/operator/review'})">运营工作区</button></view></template>
